Path('app/src/main/java/fr/neamar/kiss/notification/NotificationUnreadStore.java').write_text('''package fr.neamar.kiss.notification;\n\nimport android.content.Context;\nimport android.content.SharedPreferences;\n\nimport androidx.annotation.NonNull;\n\nimport java.util.Collections;\nimport java.util.HashSet;\nimport java.util.Set;\n\n/**\n * Persistent launcher-owned read state for exact Android notification events.\n *\n * Android does not expose a universal cross-app "read" bit. Smart S therefore treats a freshly\n * posted notification as unread, treats an explicit Smart S open/mark-read action as read, and\n * drops both states when Android removes the notification. Keeping a separate read set prevents a\n * process/service reconnect from making an already-opened but still-panel-visible notification\n * flash again.\n */\npublic final class NotificationUnreadStore {\n    private static final String PREFS = "notification-read-state";\n    private static final String UNREAD_IDS = "unread_ids";\n    private static final String READ_IDS = "read_ids";\n    private static final Object LOCK = new Object();\n\n    private NotificationUnreadStore() {}\n\n    public static void markUnread(@NonNull Context context, @NonNull String notificationId) {\n        if (notificationId.isEmpty()) return;\n        synchronized (LOCK) {\n            SharedPreferences prefs = prefs(context);\n            Set<String> unread = copy(prefs, UNREAD_IDS);\n            Set<String> read = copy(prefs, READ_IDS);\n            unread.add(notificationId);\n            read.remove(notificationId);\n            write(prefs, unread, read);\n        }\n    }\n\n    public static void markRead(@NonNull Context context, @NonNull String notificationId) {\n        if (notificationId.isEmpty()) return;\n        synchronized (LOCK) {\n            SharedPreferences prefs = prefs(context);\n            Set<String> unread = copy(prefs, UNREAD_IDS);\n            Set<String> read = copy(prefs, READ_IDS);\n            unread.remove(notificationId);\n            read.add(notificationId);\n            write(prefs, unread, read);\n        }\n    }\n\n    public static void markRemoved(@NonNull Context context, @NonNull String notificationId) {\n        if (notificationId.isEmpty()) return;\n        synchronized (LOCK) {\n            SharedPreferences prefs = prefs(context);\n            Set<String> unread = copy(prefs, UNREAD_IDS);\n            Set<String> read = copy(prefs, READ_IDS);\n            if (!unread.remove(notificationId) && !read.remove(notificationId)) return;\n            read.remove(notificationId);\n            write(prefs, unread, read);\n        }\n    }\n\n    /**\n     * Reconcile against Android's verified active set. Unknown active IDs are new/unread; IDs that\n     * Smart S already marked read stay read across listener reconnects until Android removes them.\n     */\n    public static void reconcileActive(@NonNull Context context, @NonNull Set<String> activeIds) {\n        synchronized (LOCK) {\n            SharedPreferences prefs = prefs(context);\n            Set<String> unread = copy(prefs, UNREAD_IDS);\n            Set<String> read = copy(prefs, READ_IDS);\n            unread.retainAll(activeIds);\n            read.retainAll(activeIds);\n            for (String id : activeIds) {\n                if (!read.contains(id) && !unread.contains(id)) unread.add(id);\n            }\n            write(prefs, unread, read);\n        }\n    }\n\n    public static boolean isUnread(@NonNull Context context, @NonNull String notificationId) {\n        if (notificationId.isEmpty()) return false;\n        return prefs(context).getStringSet(UNREAD_IDS, Collections.emptySet()).contains(notificationId);\n    }\n\n    private static SharedPreferences prefs(Context context) {\n        return context.getApplicationContext().getSharedPreferences(PREFS, Context.MODE_PRIVATE);\n    }\n\n    private static Set<String> copy(SharedPreferences prefs, String key) {\n        return new HashSet<>(prefs.getStringSet(key, Collections.emptySet()));\n    }\n\n    private static void write(SharedPreferences prefs, Set<String> unread, Set<String> read) {\n        prefs.edit().putStringSet(UNREAD_IDS, new HashSet<>(unread))\n                .putStringSet(READ_IDS, new HashSet<>(read)).apply();\n    }\n}\n''')

Path('app/src/main/java/fr/neamar/kiss/ui/NotificationBellPolicy.java').write_text('''package fr.neamar.kiss.ui;\n\n/** Pure policy kept separate so notification-vs-app identity and flashing rules stay testable. */\npublic final class NotificationBellPolicy {\n    private NotificationBellPolicy() {}\n\n    public static boolean shouldShow(boolean notificationEvent, boolean persistedNotificationEvent) {\n        return notificationEvent || persistedNotificationEvent;\n    }\n\n    public static boolean shouldFlash(boolean showBell, boolean unread, boolean verticalList) {\n        return showBell && unread && verticalList;\n    }\n}\n''')

Path('app/src/main/java/fr/neamar/kiss/ui/NotificationBellStyle.java').write_text('''package fr.neamar.kiss.ui;\n\nimport android.animation.ValueAnimator;\nimport android.content.Context;\nimport android.graphics.Color;\nimport android.graphics.drawable.Drawable;\nimport android.view.View;\nimport android.widget.TextView;\n\nimport androidx.annotation.NonNull;\nimport androidx.annotation.Nullable;\nimport androidx.core.content.ContextCompat;\nimport androidx.core.graphics.drawable.DrawableCompat;\n\nimport java.util.WeakHashMap;\n\nimport fr.neamar.kiss.R;\nimport fr.neamar.kiss.notification.NotificationUnreadStore;\nimport fr.neamar.kiss.pojo.NotificationHistorySearchPojo;\nimport fr.neamar.kiss.pojo.NotificationPojo;\nimport fr.neamar.kiss.pojo.Pojo;\nimport fr.neamar.kiss.result.Result;\n\n/** One strict notification-event identity rule shared by native and custom result renderers. */\npublic final class NotificationBellStyle {\n    private static final WeakHashMap<TextView, ValueAnimator> FLASHERS = new WeakHashMap<>();\n    private static final WeakHashMap<TextView, Boolean> DETACH_GUARDS = new WeakHashMap<>();\n\n    private NotificationBellStyle() {}\n\n    public static boolean isNotificationItem(@NonNull Context context,\n                                             @Nullable Result<?> result,\n                                             @Nullable View renderedSource) {\n        if (result == null || result.getPojo() == null) return false;\n        Pojo pojo = result.getPojo();\n        // Deliberately do not inspect app notification previews, package history, or rendered\n        // notification rows here. Those belong to the app-launch tile and do not change its origin.\n        return NotificationBellPolicy.shouldShow(\n                pojo instanceof NotificationPojo,\n                pojo instanceof NotificationHistorySearchPojo);\n    }\n\n    private static boolean isUnreadNotification(@NonNull Context context,\n                                                @Nullable Result<?> result) {\n        if (result == null || !(result.getPojo() instanceof NotificationPojo)) return false;\n        String id = result.getPojoId();\n        return id != null && NotificationUnreadStore.isUnread(context, id);\n    }\n\n    /** Apply to the primary name in a normal adapter row; false explicitly clears recycled rows. */\n    public static void applyToResult(@NonNull View root, @Nullable Result<?> result,\n                                     boolean verticalList) {\n        TextView primary = primaryName(root);\n        if (primary == null) return;\n        boolean show = isNotificationItem(root.getContext(), result, root);\n        boolean flash = NotificationBellPolicy.shouldFlash(\n                show, isUnreadNotification(root.getContext(), result), verticalList);\n        apply(primary, show, flash);\n    }\n\n    @Nullable\n    private static TextView primaryName(@NonNull View root) {\n        int[] ids = new int[]{R.id.item_notification_app, R.id.item_app_name,\n                R.id.item_setting_name, R.id.item_communication_title};\n        for (int id : ids) {\n            View candidate = root.findViewById(id);\n            if (candidate instanceof TextView && candidate.getVisibility() != View.GONE) {\n                return (TextView) candidate;\n            }\n        }\n        return null;\n    }\n\n    public static void apply(@NonNull TextView textView, boolean visible) {\n        apply(textView, visible, false);\n    }\n\n    public static void apply(@NonNull TextView textView, boolean visible, boolean flashUnread) {\n        stopFlashing(textView);\n        if (!visible) {\n            textView.setCompoundDrawablesRelative(null, null, null, null);\n            textView.setCompoundDrawablePadding(0);\n            return;\n        }\n\n        Drawable source = ContextCompat.getDrawable(\n                textView.getContext(), R.drawable.ic_notification_bell);\n        if (source == null) return;\n        Drawable bell = DrawableCompat.wrap(source.mutate());\n        DrawableCompat.setTint(bell, flashUnread ? Color.YELLOW : textView.getCurrentTextColor());\n        float density = textView.getResources().getDisplayMetrics().density;\n        int size = Math.max(1, Math.round(17f * density));\n        bell.setBounds(0, 0, size, size);\n        textView.setCompoundDrawablePadding(Math.round(5f * density));\n        textView.setCompoundDrawablesRelative(null, null, bell, null);\n\n        if (flashUnread) startFlashing(textView, bell);\n    }\n\n    private static void startFlashing(@NonNull TextView textView, @NonNull Drawable bell) {\n        ensureDetachGuard(textView);\n        ValueAnimator animator = ValueAnimator.ofInt(255, 55, 255);\n        animator.setDuration(900L);\n        animator.setRepeatCount(ValueAnimator.INFINITE);\n        animator.addUpdateListener(value -> {\n            Drawable[] current = textView.getCompoundDrawablesRelative();\n            if (current.length < 3 || current[2] != bell) {\n                stopFlashing(textView);\n                return;\n            }\n            bell.setAlpha((Integer) value.getAnimatedValue());\n            textView.invalidate();\n        });\n        FLASHERS.put(textView, animator);\n        animator.start();\n    }\n\n    private static void ensureDetachGuard(@NonNull TextView textView) {\n        if (DETACH_GUARDS.containsKey(textView)) return;\n        DETACH_GUARDS.put(textView, Boolean.TRUE);\n        textView.addOnAttachStateChangeListener(new View.OnAttachStateChangeListener() {\n            @Override public void onViewAttachedToWindow(View v) { }\n            @Override public void onViewDetachedFromWindow(View v) {\n                stopFlashing(textView);\n            }\n        });\n    }\n\n    private static void stopFlashing(@NonNull TextView textView) {\n        ValueAnimator previous = FLASHERS.remove(textView);\n        if (previous != null) previous.cancel();\n    }\n}\n''')

Path('app/src/test/java/fr/neamar/kiss/ui/NotificationBellPolicyTest.java').write_text('''package fr.neamar.kiss.ui;\n\nimport static org.hamcrest.MatcherAssert.assertThat;\nimport static org.hamcrest.Matchers.is;\n\nimport org.junit.jupiter.api.Test;\n\nclass NotificationBellPolicyTest {\n    @Test void appOrShortcutHistoryTileDoesNotGainBellFromAttachedNotificationContent() {\n        assertThat(NotificationBellPolicy.shouldShow(false, false), is(false));\n    }\n\n    @Test void actualNotificationEventsAlwaysKeepTheirBell() {\n        assertThat(NotificationBellPolicy.shouldShow(true, false), is(true));\n        assertThat(NotificationBellPolicy.shouldShow(false, true), is(true));\n    }\n\n    @Test void onlyUnreadVerticalListNotificationBellFlashes() {\n        assertThat(NotificationBellPolicy.shouldFlash(true, true, true), is(true));\n        assertThat(NotificationBellPolicy.shouldFlash(true, false, true), is(false));\n        assertThat(NotificationBellPolicy.shouldFlash(true, true, false), is(false));\n        assertThat(NotificationBellPolicy.shouldFlash(false, true, true), is(false));\n    }\n}\n''')
